import{_ as e}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as a,o as n,af as i}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const x=JSON.parse('{"title":"MiniMax Agent glossary","description":"No how-to. Separate Agent / Code / Hub / Design / Mini-Agent, then Lightning, Pro, and Agent Team.","frontmatter":{"title":"MiniMax Agent glossary","description":"No how-to. Separate Agent / Code / Hub / Design / Mini-Agent, then Lightning, Pro, and Agent Team.","domain":"product","tags":["coding-agent"],"role":"glossary"},"headers":[],"relativePath":"products/minimax-agent/minimax-agent-glossary.md","filePath":"products/minimax-agent/minimax-agent-glossary.md","lastUpdated":1787107158000}'),s={name:"products/minimax-agent/minimax-agent-glossary.md"};function o(r,t,l,d,g,h){return n(),a("div",null,[...t[0]||(t[0]=[i(`<h1 id="minimax-agent-glossary" tabindex="-1">MiniMax Agent glossary <a class="header-anchor" href="#minimax-agent-glossary" aria-label="Permalink to &quot;MiniMax Agent glossary&quot;">​</a></h1><p>No procedures. This page explains why the names collide. Which surface to open: <a href="./">learning map</a>.</p><h2 id="concept-map" tabindex="-1">Concept map <a class="header-anchor" href="#concept-map" aria-label="Permalink to &quot;Concept map&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Vendor MiniMax</span></span>
<span class="line"><span>├── General workbench MiniMax Agent (web)</span></span>
<span class="line"><span>│   ├── Modes: Lightning / Pro</span></span>
<span class="line"><span>│   ├── Collaboration: Agent Team (Leader / Worker / Verifier)</span></span>
<span class="line"><span>│   ├── Extension: Skill</span></span>
<span class="line"><span>│   └── On-site entries: MaxHermes / MaxClaw</span></span>
<span class="line"><span>├── Desktop coding MiniMax Code        ← not this directory</span></span>
<span class="line"><span>├── Creation MiniMax Design (EN About still says Hub)</span></span>
<span class="line"><span>├── Video Hailuo / speech Audio / characters Xingye·Talkie</span></span>
<span class="line"><span>└── Open Platform API + Token Plan</span></span></code></pre></div><h2 id="everything-named-minimax-or-agent" tabindex="-1">Everything named MiniMax or Agent <a class="header-anchor" href="#everything-named-minimax-or-agent" aria-label="Permalink to &quot;Everything named MiniMax or Agent&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Name</th><th>What it is</th><th>Where</th></tr></thead><tbody><tr><td><strong>MiniMax Agent</strong></td><td>General long-horizon workbench</td><td>agent.minimaxi.com / agent.minimax.io</td></tr><tr><td>MiniMax Code</td><td>Desktop AI agent app</td><td><a href="https://agent.minimaxi.com/docs/code/welcome" target="_blank" rel="noreferrer">welcome</a></td></tr><tr><td>MiniMax Hub</td><td>First-level name in EN About</td><td><code>hub.minimaxi.com</code> currently loads Design</td></tr><tr><td>MiniMax Design</td><td>Multimodal creation studio / canvas</td><td>design.minimaxi.com</td></tr><tr><td>Hailuo</td><td>Video product</td><td>hailuoai.com</td></tr><tr><td>MiniMax Audio</td><td>Speech and music</td><td>minimaxi.com/audio</td></tr><tr><td>Xingye</td><td>Immersive agent community</td><td>xingyeai.com</td></tr><tr><td>Talkie</td><td>Xingye overseas</td><td>talkie-ai.com</td></tr><tr><td>Mini-Agent</td><td>Open-platform sample</td><td>GitHub MiniMax-AI/Mini-Agent</td></tr><tr><td>MaxHermes</td><td>On-site &quot;cloud assistant&quot; entry</td><td>changelog 2026-04-16</td></tr><tr><td>MaxClaw</td><td>On-site settings / channels / persona entry</td><td>changelog 2026-04-11</td></tr><tr><td>Token Plan</td><td>Subscription and quota</td><td>Company Product nav</td></tr><tr><td>MiniMax M2 / M3</td><td>Driving models, not product surfaces</td><td>News and home; internals in <a href="https://llm.zenheart.site/chapters/" target="_blank" rel="noreferrer">Learn LLM</a></td></tr></tbody></table><p><strong>Not official product names. Do not write them as facts:</strong></p><ul><li>&quot;MiniMax Agent is just the web skin of Code&quot; — desktop was renamed to Code on its own.</li><li>&quot;Hub equals Agent&quot; — Hub aligns with Design, not Agent.</li><li>Treating the Mini-Agent sample repo as the product download.</li></ul><h2 id="what-minimax-agent-is-why-it-exists" tabindex="-1">What MiniMax Agent is / why it exists <a class="header-anchor" href="#what-minimax-agent-is-why-it-exists" aria-label="Permalink to &quot;What MiniMax Agent is / why it exists&quot;">​</a></h2><p><strong>What it is:</strong> A browser agent that takes a goal, splits work, and hands back files or pages. Official contrast: a reliable coworker, not an autocomplete box.</p><p><strong>Why it exists:</strong> A chat assistant stops at Q&amp;A. An agent has to plan, call tools, test, and return something you can open. The <a href="https://www.minimaxi.com/news/minimax-agent" target="_blank" rel="noreferrer">launch post</a> frames this as &quot;Code is cheap, show me the requirement.&quot;</p><p><strong>What it is not:</strong> Not a local IDE, not a Hailuo reskin, not Xingye.</p><h2 id="lightning-and-pro" tabindex="-1">Lightning and Pro <a class="header-anchor" href="#lightning-and-pro" aria-label="Permalink to &quot;Lightning and Pro&quot;">​</a></h2><p><strong>What they are:</strong> Two modes of one product, not two products.</p><p><strong>Why they exist:</strong> The <a href="https://www.minimaxi.com/en/news/minimax-m2" target="_blank" rel="noreferrer">M2 post</a> described contemporary agent products as expensive or slow. Lightning keeps short tasks fast. Pro keeps long tasks capable.</p><p><strong>Difference:</strong></p><table tabindex="0"><thead><tr><th></th><th>Lightning</th><th>Pro</th></tr></thead><tbody><tr><td>Official jobs</td><td>Q&amp;A, light search, light code</td><td>Research, full-stack, PPT, reports, sites</td></tr><tr><td>Cost</td><td>Weak on long deliverables</td><td>Heavy for a one-line question</td></tr></tbody></table><h2 id="agent-team" tabindex="-1">Agent Team <a class="header-anchor" href="#agent-team" aria-label="Permalink to &quot;Agent Team&quot;">​</a></h2><p><strong>What it is:</strong> A multi-agent system led by one agent. Official roles: Leader, Worker, Verifier. The user still sends one message.</p><p><strong>Why it exists:</strong> A single agent is both player and referee. Long jobs stop early, drift, or go silent on IM. Team turns split, parallel, and review into system behavior.</p><p><strong>What it is not:</strong> Not &quot;open three chat tabs.&quot; Not every sub-agent toggle in the Code docs.</p><p>The official article also names Team Engine states: <code>producing</code> / <code>verifying</code> / <code>done</code>. That is design language, not a command you type.</p><h2 id="skill" tabindex="-1">Skill <a class="header-anchor" href="#skill" aria-label="Permalink to &quot;Skill&quot;">​</a></h2><p><strong>What it is:</strong> An installable, reusable domain flow. Market: <a href="https://agent.minimaxi.com/skills" target="_blank" rel="noreferrer">skills</a>.</p><p><strong>Why it exists:</strong> Role-play is not role split. The Team article lists tools, context, memory, and Skill as four dimensions of division of labor. Without a skill you re-teach the flow every time.</p><p><strong>Versus plugins:</strong> The skill marketplace is a page the Agent web app opens. The plugin marketplace launch is in MiniMax Code release notes. Do not merge the two tables.</p><h2 id="hub-and-design" tabindex="-1">Hub and Design <a class="header-anchor" href="#hub-and-design" aria-label="Permalink to &quot;Hub and Design&quot;">​</a></h2><p><strong>What they are:</strong> Creation products: canvas, storyboard, finished film, local assets.</p><p><strong>Why this entry exists:</strong> EN About still lists <strong>MiniMax Hub</strong> as a first-level product. CN About lists <strong>MiniMax Design</strong>. Opening <code>hub.minimaxi.com</code> loads Design. When two official pages disagree, this site quotes both and treats the live landing page as Design.</p><p><strong>What they are not:</strong> Not another name for MiniMax Agent.</p><h2 id="related-pages" tabindex="-1">Related pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related pages&quot;">​</a></h2><ul><li><a href="./">Learning map</a></li><li><a href="./minimax-agent.html">Tutorial</a></li><li><a href="./minimax-agent-cookbook.html">Cookbook</a></li><li><a href="./minimax-agent-cheatsheet.html">Cheatsheet</a></li></ul>`,32)])])}const b=e(s,[["render",o]]);export{x as __pageData,b as default};
